const el=()=>document.querySelector('#prototype-root');
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key=p=>`ai-humanities-${p.id}`;
const save=(p,v)=>localStorage.setItem(key(p),JSON.stringify(v));
const load=(p,fallback)=>{try{return JSON.parse(localStorage.getItem(key(p)))??fallback}catch{return fallback}};
const frame=(title,desc,body)=>`<section class="prototype" aria-label="${title}"><header class="prototype-head"><h3>${title}</h3><p>${desc}</p></header><div class="prototype-body">${body}</div></section>`;
const resetButton=p=>`<button class="button ghost" type="button" data-reset>重設示例資料</button>`;
const bindReset=(p,render)=>document.querySelector('[data-reset]').addEventListener('click',()=>{localStorage.removeItem(key(p));render();});

function route(p){const spots=[['老戲院門面','建築','12'],['米店騎樓','生活','10'],['河岸倉庫','產業','15'],['舊診所窗花','建築','12'],['市場叫賣聲','生活','8'],['貨運支線碑','產業','14']];let state=load(p,[]);function render(){el().innerHTML=frame('路線組合器','選擇主題與時間，再把故事點加入路線。',`<div class="control-row"><div class="field"><label for="route-theme">故事主題</label><select id="route-theme"><option>全部</option><option>建築</option><option>生活</option><option>產業</option></select></div><div class="field"><label for="route-time">可用時間</label><select id="route-time"><option value="30">30 分鐘</option><option value="45">45 分鐘</option><option value="60">60 分鐘</option></select></div>${resetButton(p)}</div><p id="route-summary" class="feedback" aria-live="polite"></p><div class="grid two" id="route-spots"></div>`);const theme=document.querySelector('#route-theme'),time=document.querySelector('#route-time'),list=document.querySelector('#route-spots'),summary=document.querySelector('#route-summary');function draw(){const max=+time.value,total=state.reduce((n,i)=>n+(+spots[i][2]),0);summary.textContent=`目前 ${state.length} 站，預估 ${total} 分鐘（上限 ${max} 分鐘）${total>max?'；已超出時間，請移除一站。':''}`;list.innerHTML=spots.map((s,i)=>({s,i})).filter(x=>theme.value==='全部'||x.s[1]===theme.value).map(({s,i})=>`<article class="app-item ${state.includes(i)?'selected':''}"><b>${s[0]}</b><p>${s[1]}故事 · 約 ${s[2]} 分鐘</p><button class="small-button ${state.includes(i)?'':'primary'}" data-spot="${i}">${state.includes(i)?'移出路線':'加入路線'}</button></article>`).join('');list.querySelectorAll('[data-spot]').forEach(b=>b.onclick=()=>{const i=+b.dataset.spot;state=state.includes(i)?state.filter(x=>x!==i):[...state,i];save(p,state);draw()})}theme.onchange=draw;time.onchange=draw;bindReset(p,()=>{state=[];render()});draw()}render()}

function notes(p){const defaults=[{q:'雨停之後，屋瓦仍保留微光。',n:'光像是記憶留下的痕跡。',t:'光影'}];let notes=load(p,defaults);function render(){el().innerHTML=frame('意象筆記本','新增筆記並用意象標籤回看。',`<form id="note-form" class="control-row"><div class="field"><label for="quote">閱讀片段</label><input id="quote" required></div><div class="field"><label for="thought">我的想法</label><input id="thought" required></div><div class="field"><label for="note-tag">意象</label><select id="note-tag"><option>光影</option><option>聲音</option><option>移動</option></select></div><button class="button" type="submit">儲存筆記</button></form><div class="control-row"><button class="small-button primary" data-filter="全部">全部</button>${['光影','聲音','移動'].map(x=>`<button class="small-button" data-filter="${x}">${x}</button>`).join('')}${resetButton(p)}</div><div class="item-list" id="notes"></div>`);let filter='全部';const list=document.querySelector('#notes');function draw(){const shown=notes.map((n,i)=>({n,i})).filter(({n})=>filter==='全部'||n.t===filter);list.innerHTML=shown.length?shown.map(({n,i})=>`<article class="app-item"><span class="tag">${n.t}</span><blockquote>「${esc(n.q)}」</blockquote><p>${esc(n.n)}</p><button class="small-button" data-del="${i}">刪除</button></article>`).join(''):'<p class="empty">尚無符合的筆記。</p>';list.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{notes.splice(+b.dataset.del,1);save(p,notes);draw()})}document.querySelector('#note-form').onsubmit=e=>{e.preventDefault();notes.push({q:e.target.quote.value,n:e.target.thought.value,t:e.target['note-tag'].value});save(p,notes);e.target.reset();draw()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;draw()});bindReset(p,()=>{notes=structuredClone(defaults);save(p,notes);render()});draw()}render()}

function transcript(p){const lines=['P01｜我們搬來時，車站旁還是一排低矮房子。','P02｜母親每天走過河堤去市場，總說風的味道不同。','P03｜工廠關閉後，許多人離開，街上忽然安靜。','P04｜多年後回來，我先認出的是那棵榕樹。'];let clips=load(p,[]);function render(){el().innerHTML=frame('逐字稿摘錄桌','勾選片段，選擇分類後加入摘錄。',`<form id="clip-form"><fieldset class="card"><legend>示例逐字稿</legend>${lines.map((x,i)=>`<label class="app-item" style="display:block"><input type="checkbox" name="line" value="${i}"> ${x}</label>`).join('')}</fieldset><div class="control-row"><div class="field"><label for="clip-tag">分類</label><select id="clip-tag"><option>人物</option><option>地點</option><option>事件</option></select></div><button class="button" type="submit">加入摘錄</button>${resetButton(p)}</div></form><div id="clips" class="item-list" aria-live="polite"></div>`);function draw(){document.querySelector('#clips').innerHTML=clips.length?clips.map((c,i)=>`<article class="app-item"><span class="tag">${c.tag}</span><p>${lines[c.line]}</p><button class="small-button" data-del="${i}">移除</button></article>`).join(''):'<p class="empty">尚未加入片段。</p>';document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{clips.splice(+b.dataset.del,1);save(p,clips);draw()})}document.querySelector('#clip-form').onsubmit=e=>{e.preventDefault();const chosen=[...e.target.querySelectorAll('[name=line]:checked')];chosen.forEach(x=>{if(!clips.some(c=>c.line==x.value))clips.push({line:+x.value,tag:e.target['clip-tag'].value})});save(p,clips);draw()};bindReset(p,()=>{clips=[];render()});draw()}render()}

function language(p){const qs=[{scene:'市場買菜',q:'想禮貌詢問價格，哪一句較合宜？',a:['這偌濟錢？','食飽未？','你欲佗位？'],ok:0,why:'「這偌濟錢？」用來詢問這個多少錢。'},{scene:'家中用餐',q:'招呼家人一起吃飯，可選哪一句？',a:['緊來食飯。','落雨矣。','我欲轉去。'],ok:0,why:'「緊來食飯」是在熟悉情境中招呼趕快來吃飯。'},{scene:'巷口相遇',q:'詢問熟人要去哪裡，哪一句適合？',a:['你欲去佗位？','這偌濟錢？','我食飽矣。'],ok:0,why:'「你欲去佗位？」是詢問對方要去哪裡。'}];let i=0,score=0;function render(){const q=qs[i];el().innerHTML=frame('情境練習','選一個日常情境句，回答後閱讀使用說明。',`<p class="team-id">${q.scene} · 第 ${i+1}/${qs.length} 題</p><h3>${q.q}</h3><div class="item-list">${q.a.map((x,j)=>`<button class="app-item" data-answer="${j}" type="button">${x}</button>`).join('')}</div><div id="answer-feedback" aria-live="polite"></div><p>目前答對：<b>${score}</b></p><button class="button ghost" data-reset type="button">重新開始</button>`);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const ok=+b.dataset.answer===q.ok;if(ok)score++;document.querySelector('#answer-feedback').innerHTML=`<div class="feedback"><b>${ok?'回答合宜':'再想想看'}</b><br>${q.why}</div><button class="button" id="next" type="button">${i===qs.length-1?'查看結果':'下一題'}</button>`;document.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);document.querySelector('#next').onclick=()=>{if(i===qs.length-1){alert(`練習完成：答對 ${score} / ${qs.length} 題`);i=0;score=0}else i++;render()}});document.querySelector('[data-reset]').onclick=()=>{i=0;score=0;render()}}render()}

function events(p){const events=[['紙上城市工作坊','工作坊','免費','13:00','14:30'],['地方聲音散步','走讀','150 元','14:00','15:30'],['小誌交換會','市集','免費','15:00','16:30'],['老屋影像展','展覽','免費','10:00','17:00'],['城市記憶講座','講座','免費','16:00','17:30']];let plan=load(p,[]);function render(){el().innerHTML=frame('文化活動行程器','依類型與費用篩選，再加入一日行程。',`<div class="control-row"><div class="field"><label for="event-type">類型</label><select id="event-type"><option>全部</option>${[...new Set(events.map(x=>x[1]))].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label for="event-cost">費用</label><select id="event-cost"><option>全部</option><option>免費</option></select></div>${resetButton(p)}</div><div class="grid two"><div><h3>活動</h3><div id="event-list" class="item-list"></div></div><div><h3>我的行程</h3><div id="plan-list" class="item-list"></div></div></div>`);const toM=t=>+t.slice(0,2)*60 + +t.slice(3);function conflict(i){return plan.some(j=>toM(events[i][3])<toM(events[j][4])&&toM(events[i][4])>toM(events[j][3]))}function draw(){const type=document.querySelector('#event-type').value,cost=document.querySelector('#event-cost').value;document.querySelector('#event-list').innerHTML=events.map((x,i)=>({x,i})).filter(({x})=>(type==='全部'||x[1]===type)&&(cost==='全部'||x[2]===cost)).map(({x,i})=>`<article class="app-item"><b>${x[0]}</b><p>${x[1]} · ${x[2]} · ${x[3]}–${x[4]}</p><button class="small-button primary" data-add="${i}" ${plan.includes(i)||conflict(i)?'disabled':''}>${plan.includes(i)?'已加入':conflict(i)?'時段重疊':'加入行程'}</button></article>`).join('');document.querySelector('#plan-list').innerHTML=plan.length?plan.sort((a,b)=>events[a][3].localeCompare(events[b][3])).map(i=>`<article class="app-item"><b>${events[i][3]} ${events[i][0]}</b><button class="small-button" data-del="${i}">移除</button></article>`).join(''):'<p class="empty">尚未加入活動。</p>';document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{plan.push(+b.dataset.add);save(p,plan);draw()});document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{plan=plan.filter(x=>x!==+b.dataset.del);save(p,plan);draw()})}document.querySelector('#event-type').onchange=draw;document.querySelector('#event-cost').onchange=draw;bindReset(p,()=>{plan=[];render()});draw()}render()}

function sorter(p,mode='exhibit'){const isStory=mode==='story';const initial=isStory?[['離家前夜','開端','2018'],['第一次迷路','轉折','2018'],['收到家書','轉折','2019'],['再次回到車站','回望','2024']]:[['市場木牌','日常物件'],['工廠打卡鐘','勞動記憶'],['家庭合照','私人記憶'],['街區請願書','公共記憶']];let items=load(p,initial);function render(){el().innerHTML=frame(isStory?'故事拼頁':'展序工作桌',isStory?'新增或排列故事片段，再預覽敘事。':'用按鈕調整展件順序，預覽敘事動線。',`${isStory?`<form id="add-story" class="control-row"><div class="field"><label for="story-title">片段標題</label><input id="story-title" required></div><div class="field"><label for="story-role">敘事角色</label><select id="story-role"><option>開端</option><option>轉折</option><option>回望</option></select></div><div class="field"><label for="story-year">年份</label><input id="story-year" type="number" value="2024" required></div><button class="button" type="submit">新增片段</button></form>`:''}<div class="item-list" id="sort-list"></div><div class="feedback" id="sort-preview" aria-live="polite"></div><div class="actions">${isStory?'<button class="button secondary" id="by-year" type="button">依時間排序</button>':''}${resetButton(p)}</div>`);function draw(){document.querySelector('#sort-list').innerHTML=items.map((x,i)=>`<article class="app-item"><b>${i+1}. ${esc(x[0])}</b><p>${esc(x[1])}${isStory?' · '+esc(x[2]):''}</p><div class="item-actions"><button class="small-button" data-up="${i}" ${i===0?'disabled':''}>前移</button><button class="small-button" data-down="${i}" ${i===items.length-1?'disabled':''}>後移</button>${isStory?`<button class="small-button" data-del="${i}">刪除</button>`:''}</div></article>`).join('');document.querySelector('#sort-preview').textContent=(isStory?'敘事預覽：':'動線預覽：')+items.map(x=>x[0]).join(' → ');document.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>move(+b.dataset.up,-1));document.querySelectorAll('[data-down]').forEach(b=>b.onclick=()=>move(+b.dataset.down,1));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{items.splice(+b.dataset.del,1);save(p,items);draw()})}function move(i,d){[items[i],items[i+d]]=[items[i+d],items[i]];save(p,items);draw()}if(isStory){document.querySelector('#add-story').onsubmit=e=>{e.preventDefault();items.push([e.target['story-title'].value,e.target['story-role'].value,e.target['story-year'].value]);save(p,items);render()};document.querySelector('#by-year').onclick=()=>{items.sort((a,b)=>+a[2]-+b[2]);save(p,items);draw()}}bindReset(p,()=>{items=structuredClone(initial);save(p,items);render()});draw()}render()}

function timeline(p){const initial=[{y:1968,approx:true,title:'搬進河邊的新家',source:'相簿背面鉛筆字'},{y:1982,approx:false,title:'老店重新開張',source:'照片日期戳'}];let items=load(p,initial);function render(){el().innerHTML=frame('照片故事時間軸','新增事件並誠實標示日期是否約略。',`<form id="time-form" class="control-row"><div class="field"><label for="event-title">事件</label><input id="event-title" required></div><div class="field"><label for="event-year">年份</label><input id="event-year" type="number" min="1900" max="2100" required></div><div class="field"><label for="event-source">資料來源</label><input id="event-source" required></div><label><input id="event-approx" type="checkbox"> 約略年份</label><button class="button" type="submit">加入時間軸</button>${resetButton(p)}</form><div id="time-list" class="item-list"></div>`);function draw(){items.sort((a,b)=>a.y-b.y);document.querySelector('#time-list').innerHTML=items.map((x,i)=>`<article class="app-item"><span class="team-id">${x.approx?'約 ':''}${x.y}</span><h3>${esc(x.title)}</h3><p>來源：${esc(x.source)}</p><button class="small-button" data-del="${i}">刪除</button></article>`).join('');document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{items.splice(+b.dataset.del,1);save(p,items);draw()})}document.querySelector('#time-form').onsubmit=e=>{e.preventDefault();items.push({y:+e.target['event-year'].value,approx:e.target['event-approx'].checked,title:e.target['event-title'].value,source:e.target['event-source'].value});save(p,items);render()};bindReset(p,()=>{items=structuredClone(initial);save(p,items);render()});draw()}render()}

function fieldnotes(p){const initial=[{text:'入口處的人多停在遮雨棚下交談。',type:'觀察',time:'09:12'},{text:'想追問攤位移動是否和天氣有關。',type:'待查',time:'09:16'}];let items=load(p,initial);function render(){el().innerHTML=frame('場域手帖','快速區分看見的事、感受與待查問題。',`<form id="field-form" class="control-row"><div class="field"><label for="field-text">短筆記</label><input id="field-text" required></div><div class="field"><label for="field-type">分類</label><select id="field-type"><option>觀察</option><option>感受</option><option>待查</option></select></div><button class="button" type="submit">加入手帖</button></form><div class="control-row"><div class="field"><label for="field-filter">篩選</label><select id="field-filter"><option>全部</option><option>觀察</option><option>感受</option><option>待查</option></select></div><button class="button secondary" id="copy-summary" type="button">複製摘要</button>${resetButton(p)}</div><p id="copy-status" aria-live="polite"></p><div id="field-list" class="item-list"></div>`);function draw(){const f=document.querySelector('#field-filter').value;const shown=items.filter(x=>f==='全部'||x.type===f);document.querySelector('#field-list').innerHTML=shown.map((x,i)=>`<article class="app-item"><span class="tag">${x.type}</span> <small>${x.time}</small><p>${esc(x.text)}</p><button class="small-button" data-del="${i}">刪除</button></article>`).join('')||'<p class="empty">目前沒有此類筆記。</p>';document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{items.splice(+b.dataset.del,1);save(p,items);draw()})}document.querySelector('#field-form').onsubmit=e=>{e.preventDefault();items.push({text:e.target['field-text'].value,type:e.target['field-type'].value,time:new Date().toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'})});save(p,items);e.target.reset();draw()};document.querySelector('#field-filter').onchange=draw;document.querySelector('#copy-summary').onclick=async()=>{await navigator.clipboard.writeText(items.map(x=>`[${x.type}] ${x.text}`).join('\n'));document.querySelector('#copy-status').textContent='摘要已複製。'};bindReset(p,()=>{items=structuredClone(initial);save(p,items);render()});draw()}render()}

function keywords(p){const sample='午後的雨落在老街。雨聲穿過騎樓，街角的燈逐一亮起。有人在燈下等候，也有人沿著老街慢慢回家。';const stop=['的','在','也','有人','逐一','慢慢'];function render(){el().innerHTML=frame('詞線探讀','這是透明的簡易字串統計，不是語意分析；頻率不等於重要性。',`<div class="field"><label for="source-text">輸入短文</label><textarea id="source-text">${sample}</textarea></div><div class="actions"><button class="button" id="analyze" type="button">分析詞彙</button><button class="button ghost" data-reset type="button">重設示例</button></div><div class="grid two"><div><h3>詞頻線索</h3><div id="word-list" class="item-list"></div></div><div><h3>回到原文</h3><p id="highlight-text" class="app-item"></p></div></div>`);const known=['老街','雨','雨聲','騎樓','街角','燈','燈下','等候','回家','午後'];function analyze(){const text=document.querySelector('#source-text').value;const counts=known.map(w=>[w,(text.match(new RegExp(w,'g'))||[]).length]).filter(x=>x[1]&&!stop.includes(x[0])).sort((a,b)=>b[1]-a[1]);document.querySelector('#word-list').innerHTML=counts.map(([w,n])=>`<button class="app-item" data-word="${w}" type="button"><b>${w}</b> · ${n} 次<div class="bar"><span style="width:${Math.min(100,n*40)}%"></span></div></button>`).join('')||'<p class="empty">尚未找到內建詞表中的線索。</p>';document.querySelector('#highlight-text').textContent=text;document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{const w=b.dataset.word;document.querySelector('#highlight-text').innerHTML=esc(text).replaceAll(w,`<mark>${w}</mark>`)})}document.querySelector('#analyze').onclick=analyze;document.querySelector('[data-reset]').onclick=()=>{document.querySelector('#source-text').value=sample;analyze()};analyze()}render()}

export function mountPrototype(p){({route,notes,transcript,language,events,exhibit:x=>sorter(x,'exhibit'),timeline,fieldnotes,keywords,story:x=>sorter(x,'story')}[p.prototype]||route)(p)}
